//! The Programs activity types the kernel allocates and the ledger operation
//! tag their receipts carry.
//!
//! `MODULE_ID`, the ordinal table and the three named ordinals are generated by
//! the crate build script from the `LX_PROGRAMS_*` activity type enumerators of
//! `include/layerx/programs.h`, so nothing here holds a second hand-written
//! module identifier or ordinal.

use crate::payload::{ActivityType, ModuleId};

include!(concat!(env!("OUT_DIR"), "/programs_activity.rs"));

/// Returns the ledger operation tag the kernel writes into the receipt of a
/// Programs activity submitted at `ordinal`.
///
/// `receipt_bind_program_operation` in `src/protocol/lxp_kernel.c` binds the
/// call ordinal into a state-commitment receipt for `LX_PROGRAMS_CALL` alone.
/// Every other Programs activity leaves the tag at zero: that is the lifecycle
/// receipt shape the core, gateway, authority and emulator verifiers require of
/// a deploy or an upgrade, and the shape `lxp_programs_project_receipt_events`
/// in `src/modules/programs/event.c` projects without committed events. The
/// activity ordinal a route submits is therefore not the operation its receipt
/// reports.
#[must_use]
pub const fn receipt_operation(ordinal: u16) -> u8 {
    if ordinal == CALL_ORDINAL {
        CALL_OPERATION
    } else {
        0
    }
}

/// Returns the activity type the kernel allocates for `ordinal`.
///
/// # Errors
///
/// Returns [`crate::payload::PayloadError::ZeroOrdinal`] when `ordinal` is zero.
pub const fn activity_type(ordinal: u16) -> Result<ActivityType, crate::payload::PayloadError> {
    ActivityType::new(ModuleId::Programs, ordinal)
}

#[cfg(test)]
mod tests {
    use super::{
        activity_type, receipt_operation, CALL_OPERATION, CALL_ORDINAL, DEPLOY_ORDINAL, MODULE_ID,
        ORDINALS, UPGRADE_ORDINAL,
    };
    use crate::payload::ModuleId;

    const PROGRAMS_HEADER: &str = include_str!("../../../../include/layerx/programs.h");

    fn header_activity_types() -> Vec<(String, u32)> {
        let mut types = Vec::new();
        for raw in PROGRAMS_HEADER.lines() {
            let line = raw.trim();
            let Some(rest) = line.strip_prefix("LX_PROGRAMS_") else {
                continue;
            };
            let Some((suffix, value)) = rest.split_once(" = ") else {
                continue;
            };
            let Some(digits) = value.trim_end_matches(',').trim().strip_prefix("0x") else {
                continue;
            };
            let value = u32::from_str_radix(digits, 16)
                .unwrap_or_else(|error| panic!("invalid activity type number in {line}: {error}"));
            types.push((format!("LX_PROGRAMS_{suffix}"), value));
        }
        assert!(
            !types.is_empty(),
            "include/layerx/programs.h declares no Programs activity type"
        );
        types
    }

    #[test]
    fn ordinals_mirror_the_kernel_headers_programs_activity_types() {
        let declared = header_activity_types();
        assert_eq!(declared.len(), ORDINALS.len());
        for ((name, value), (mirrored, ordinal)) in declared.iter().zip(ORDINALS.iter()) {
            assert_eq!(name.as_str(), *mirrored, "{name}");
            assert_eq!(*value >> 16, u32::from(MODULE_ID), "{name}");
            assert_eq!(*value & 0xffff, u32::from(*ordinal), "{name}");
        }
    }

    #[test]
    fn named_ordinals_pack_onto_the_protocol_module_set() {
        let declared = header_activity_types();
        for (name, ordinal) in [
            ("LX_PROGRAMS_DEPLOY", DEPLOY_ORDINAL),
            ("LX_PROGRAMS_UPGRADE", UPGRADE_ORDINAL),
            ("LX_PROGRAMS_CALL", CALL_ORDINAL),
        ] {
            let (_, value) = declared
                .iter()
                .find(|(declared, _)| declared == name)
                .unwrap_or_else(|| panic!("{name} is not declared"));
            let activity =
                activity_type(ordinal).unwrap_or_else(|_| panic!("{name} activity type"));
            assert_eq!(activity.value(), *value, "{name}");
            assert_eq!(activity.module(), ModuleId::Programs, "{name}");
            assert_eq!(activity.ordinal(), ordinal, "{name}");
        }
    }

    #[test]
    fn receipt_operation_binds_the_call_ordinal_alone() {
        assert_eq!(u32::from(CALL_OPERATION), u32::from(CALL_ORDINAL));
        assert_eq!(receipt_operation(CALL_ORDINAL), CALL_OPERATION);
        assert_eq!(receipt_operation(DEPLOY_ORDINAL), 0);
        assert_eq!(receipt_operation(UPGRADE_ORDINAL), 0);
        for (name, ordinal) in ORDINALS {
            let expected = if ordinal == CALL_ORDINAL {
                CALL_OPERATION
            } else {
                0
            };
            assert_eq!(receipt_operation(ordinal), expected, "{name}");
        }
        assert_eq!(receipt_operation(0), 0);
        assert_eq!(receipt_operation(u16::MAX), 0);
    }
}
